solution.js:
const preis = 8;
const anzahl = 3;
const summe = document.getElementById("summe");
const rechnenKnopf = document.getElementById("rechnen-knopf");
rechnenKnopf.addEventListener("click", function () {
  summe.textContent = "Summe: " + preis * anzahl + " €";
});

